/* Biblioteca de ofimatica: texto dinamico, ZIP, importacion y editor con ajuste de linea */
#include "z.h"
void sb_add(sb_t *b, const void *d, long n) { if (b->n + n + 1 > b->cap) { long c = (b->n + n) * 2 + 4096; b->p = realloc(b->p, c); b->cap = c; } memcpy(b->p + b->n, d, n); b->n += n; b->p[b->n] = 0; }
void sb_s(sb_t *b, const char *s) { sb_add(b, s, strlen(s)); }
void sb_f(sb_t *b, const char *f, ...) { char t[1024]; va_list a; va_start(a, f); int n = vsnprintf(t, 1024, f, a); va_end(a); sb_add(b, t, MIN(n, 1023)); }
void sb_esc(sb_t *b, const char *s, long n) { for (long i = 0; i < n; i++) { char c = s[i]; if (c == '&') sb_s(b, "&amp;"); else if (c == '<') sb_s(b, "&lt;"); else if (c == '>') sb_s(b, "&gt;"); else if (c == '"') sb_s(b, "&quot;"); else sb_add(b, &c, 1); } }
static u32 crct[256]; u32 z_crc_add(u32 c, const u8 *d, long n) { if (!crct[1]) for (u32 i = 0; i < 256; i++) { u32 v = i; for (int k = 0; k < 8; k++) v = v >> 1 ^ (0xEDB88320 & -(v & 1)); crct[i] = v; } c = ~c; for (long i = 0; i < n; i++) c = crct[(c ^ d[i]) & 255] ^ c >> 8; return ~c; }
u32 z_crc32(const u8 *d, long n) { return z_crc_add(0, d, n); }
#define L16(p) ((p)[0] | (p)[1] << 8)
#define L32(p) ((u32)(p)[0] | (p)[1] << 8 | (p)[2] << 16 | (u32)(p)[3] << 24)
u8 *zip_get(const u8 *z, long n, const char *name, long *out) {
    long e = n - 22; while (e >= 0 && e > n - 66000 && L32(z + e) != 0x06054B50) e--; if (e < 0 || L32(z + e) != 0x06054B50) return 0; int cnt = L16(z + e + 10); long p = L32(z + e + 16), nl_ = strlen(name);
    for (int i = 0; i < cnt && p + 46 <= n; i++) { const u8 *h = z + p; if (L32(h) != 0x02014B50) return 0; int nl = L16(h + 28), xl = L16(h + 30), cl = L16(h + 32), m = L16(h + 10); u32 cs = L32(h + 20), us = L32(h + 24), lo = L32(h + 42); if (nl == nl_ && !memcmp(h + 46, name, nl)) { const u8 *l = z + lo; if (lo + 30 > (u64)n) return 0; const u8 *d = l + 30 + L16(l + 26) + L16(l + 28); if (d + cs > z + n) return 0; u8 *o = malloc(us + 1); if (m == 0) memcpy(o, d, us); else if (m != 8 || z_inflate(d, cs, o, us) < 0) { free(o); return 0; } o[us] = 0; if (out) *out = us; return o; } p += 46 + nl + xl + cl; } return 0;
}
static void w16(sb_t *b, u32 v) { u8 t[2] = {v, v >> 8}; sb_add(b, t, 2); } static void w32(sb_t *b, u32 v) { u8 t[4] = {v, v >> 8, v >> 16, v >> 24}; sb_add(b, t, 4); }
int zip_save(const char *path, int c, const char **nm, const char **d, const long *ln) { sb_t z = {0}, cd = {0}; for (int i = 0; i < c; i++) { u32 crc = z_crc32((const u8 *)d[i], ln[i]), o = z.n; int nl = strlen(nm[i]); w32(&z, 0x04034B50); w16(&z, 20); w16(&z, 0x800); w16(&z, 0); w16(&z, 0); w16(&z, 0x5A21); w32(&z, crc); w32(&z, ln[i]); w32(&z, ln[i]); w16(&z, nl); w16(&z, 0); sb_add(&z, nm[i], nl); sb_add(&z, d[i], ln[i]); w32(&cd, 0x02014B50); w16(&cd, 20); w16(&cd, 20); w16(&cd, 0x800); w16(&cd, 0); w16(&cd, 0); w16(&cd, 0x5A21); w32(&cd, crc); w32(&cd, ln[i]); w32(&cd, ln[i]); w16(&cd, nl); w16(&cd, 0); w16(&cd, 0); w16(&cd, 0); w16(&cd, 0); w32(&cd, 0); w32(&cd, o); sb_add(&cd, nm[i], nl); } u32 co = z.n; sb_add(&z, cd.p, cd.n); w32(&z, 0x06054B50); w16(&z, 0); w16(&z, 0); w16(&z, c); w16(&z, c); w32(&z, cd.n); w32(&z, co); w16(&z, 0); int e = z_writefile(path, z.p, z.n); free(z.p); free(cd.p); return e; }
int z_ends(const char *s, const char *e) { int a = strlen(s), b = strlen(e); return a >= b && !strcasecmp(s + a - b, e); }
void z_docdir(char *o) { zdirent d; if (z_stat("/sys", &d)) strcpy(o, "/rd/tmp"); else { strcpy(o, "/sys/DOCS"); z_mkdir(o); } }
static void put_ent(sb_t *b, const char **ps) { const char *p = *ps; char o[5]; int c = -1, l = 0; if (!strncmp(p, "&amp;", 5)) { c = '&'; l = 5; } else if (!strncmp(p, "&lt;", 4)) { c = '<'; l = 4; } else if (!strncmp(p, "&gt;", 4)) { c = '>'; l = 4; } else if (!strncmp(p, "&quot;", 6)) { c = '"'; l = 6; } else if (!strncmp(p, "&apos;", 6)) { c = '\''; l = 6; } else if (p[1] == '#') { const char *e = strchr(p, ';'); if (e) { c = p[2] == 'x' ? 0 : atoi(p + 2); if (p[2] == 'x') for (const char *q = p + 3; q < e; q++) { int x = tolower(*q); c = c * 16 + (isdigit(x) ? x - '0' : x - 'a' + 10); } l = e - p + 1; } } if (c >= 0) { int n = utf8_put(c, o); sb_add(b, o, n); *ps = p + l; } else { sb_add(b, p, 1); *ps = p + 1; } }
static char *xml_text(const char *x, const char *para, const char *txt) { sb_t b = {0}; int inp = 0, intx = !txt; int pl = strlen(para), tl = txt ? strlen(txt) : 0; sb_s(&b, ""); for (const char *p = x; *p;) { if (*p == '<') { const char *e = strchr(p, '>'); if (!e) break; int cl = p[1] == '/'; const char *n = p + 1 + cl; if ((!strncmp(n, para, pl) || (pl == 6 && !strncmp(para, "text:p", 6) && !strncmp(n, "text:h", 6))) && (n[pl] == ' ' || n[pl] == '>' || n[pl] == '/')) { if (cl || e[-1] == '/') sb_s(&b, "\n"); inp = !cl; } else if (txt && !strncmp(n, txt, tl) && (n[tl] == ' ' || n[tl] == '>')) intx = !cl; else if (!strncmp(n, "w:tab/", 6) || !strncmp(n, "text:tab", 8)) sb_s(&b, "\t"); else if (!strncmp(n, "w:br", 4) || !strncmp(n, "text:line-break", 15)) sb_s(&b, "\n"); else if (!strncmp(n, "text:s", 6) && (n[6] == '/' || n[6] == ' ')) sb_s(&b, " "); p = e + 1; continue; } if (inp && intx) { if (*p == '&') put_ent(&b, &p); else sb_add(&b, p++, 1); } else p++; } return b.p; }
static char *rtf_text(const char *s) { sb_t b = {0}; sb_s(&b, ""); int skip = 0, d = 0, sk[64] = {0}; for (const char *p = s; *p;) { char c = *p; if (c == '{') { if (d < 63) d++; sk[d] = skip; p++; } else if (c == '}') { skip = sk[d]; if (d) d--; p++; } else if (c == '\\') { p++; if (*p == '\'') { int v = 0; for (int i = 1; i <= 2; i++) { int x = tolower(p[i]); v = v * 16 + (isdigit(x) ? x - '0' : x - 'a' + 10); } if (!skip) { char o[4]; int n = utf8_put(v, o); sb_add(&b, o, n); } p += 3; } else if (isalpha(*p)) { char w[16]; int k = 0; while (isalpha(*p)) { if (k < 15) w[k++] = *p; p++; } w[k] = 0; int neg = *p == '-', v = 0, has = 0; if (neg) p++; while (isdigit(*p)) { v = v * 10 + *p++ - '0'; has = 1; } if (*p == ' ') p++; if (neg) v = -v; if (!strcmp(w, "par") || !strcmp(w, "line")) { if (!skip) sb_s(&b, "\n"); } else if (!strcmp(w, "tab")) { if (!skip) sb_s(&b, "\t"); } else if (!strcmp(w, "u") && has) { if (!skip) { char o[4]; int n = utf8_put(v < 0 ? v + 65536 : v, o); sb_add(&b, o, n); } if (*p == '?') p++; } else if (!strcmp(w, "fonttbl") || !strcmp(w, "colortbl") || !strcmp(w, "stylesheet") || !strcmp(w, "info") || !strcmp(w, "pict")) skip = 1; } else { if (*p == '*') skip = 1; else if (*p && !skip && !isalpha(*p) && *p != '\n' && *p != '\r') sb_add(&b, p, 1); if (*p) p++; } } else { if (c != '\n' && c != '\r' && !skip) sb_add(&b, p, 1); p++; } } return b.p; }
char *doc_import(const char *path, long *len) { long n; u8 *d = z_readfile(path, &n); if (!d) return 0; char *r = 0; if (z_ends(path, ".docx")) { long l; u8 *x = zip_get(d, n, "word/document.xml", &l); if (x) { r = xml_text((char *)x, "w:p", "w:t"); free(x); } free(d); } else if (z_ends(path, ".odt")) { long l; u8 *x = zip_get(d, n, "content.xml", &l); if (x) { sb_t t = {0}; r = xml_text((char *)x, "text:p", 0); char *h = 0; (void)t; (void)h; free(x); } free(d); } else if (z_ends(path, ".rtf")) { r = rtf_text((char *)d); free(d); } else r = (char *)d; if (r && len) *len = strlen(r); return r; }
int te_words(const char *s, long n) { int c = 0, w = 0; for (long i = 0; i < n; i++) { int sp = isspace((u8)s[i]); if (!sp && !w) c++; w = !sp; } return c; }
void te_init(te_t *t) { memset(t, 0, sizeof *t); t->cap = 65536; t->t = calloc(1, t->cap); t->sel = -1; t->cols = 72; t->changed = 1; }
static void need(te_t *t, long n) { if (t->len + n + 1 > t->cap) { t->cap = (t->len + n) * 2 + 4096; t->t = realloc(t->t, t->cap); } }
static void undo_clear(te_t *t);
void te_set(te_t *t, const char *s, long n) { undo_clear(t); t->len = 0; t->cur = 0; t->sel = -1; t->top = 0; need(t, n); memcpy(t->t, s, n); t->len = n; t->t[n] = 0; t->changed = 1; }
void te_layout(te_t *t, int cols) { if (!t->changed && cols == t->cols && t->ln) return; t->cols = cols; t->changed = 0; t->nl = 0; long p = 0; for (;;) { if (t->nl + 2 >= t->lcap) { t->lcap = t->lcap ? t->lcap * 2 : 1024; t->ln = realloc(t->ln, t->lcap * sizeof(long)); } t->ln[t->nl++] = p; long q = p, br = -1; int c = 0; while (q < t->len && t->t[q] != '\n' && c < cols) { if (t->t[q] == ' ') br = q + 1; q++; while (q < t->len && (t->t[q] & 0xC0) == 0x80) q++; c++; } if (q >= t->len) break; if (t->t[q] == '\n') p = q + 1; else { if (t->t[q] == ' ') p = q + 1; else p = br > p ? br : q; } } t->ln[t->nl] = t->len + 1; }
int te_line_of(te_t *t, long p) { int a = 0, b = t->nl - 1; while (a < b) { int m = (a + b + 1) / 2; if (t->ln[m] <= p) a = m; else b = m - 1; } return a; }
static long at_col(te_t *t, int l, int c) { long p = t->ln[l], e = t->ln[l + 1] - 1; if (l + 1 >= t->nl) e = t->len; while (p < e && c > 0 && p < t->len && t->t[p] != '\n') { p++; while (p < t->len && (t->t[p] & 0xC0) == 0x80) p++; c--; } return p; }
static int col_of(te_t *t, int l, long pos) { int c = 0; for (long p = t->ln[l]; p < pos; p++) if ((t->t[p] & 0xC0) != 0x80) c++; return c; }
static void del_(te_t *t, long a, long b) { memmove(t->t + a, t->t + b, t->len - b + 1); t->len -= b - a; t->cur = a; t->sel = -1; t->changed = 1; }
static void ins_(te_t *t, const char *s, long n) { need(t, n); memmove(t->t + t->cur + n, t->t + t->cur, t->len - t->cur + 1); memcpy(t->t + t->cur, s, n); t->cur += n; t->len += n; t->changed = 1; }
static void del_sel(te_t *t) { if (t->sel >= 0 && t->sel != t->cur) del_(t, MIN(t->sel, t->cur), MAX(t->sel, t->cur)); t->sel = -1; }
static int te_key0(te_t *t, zevent *e, int page) { te_layout(t, t->cols); long c0 = t->cur; int k = e->key, sh = e->mods & M_SHIFT, mv = 1, l = te_line_of(t, t->cur), col = col_of(t, l, t->cur); if (k == K_LEFT) { if (t->cur) { t->cur--; while (t->cur && (t->t[t->cur] & 0xC0) == 0x80) t->cur--; } } else if (k == K_RIGHT) { if (t->cur < t->len) { t->cur++; while (t->cur < t->len && (t->t[t->cur] & 0xC0) == 0x80) t->cur++; } } else if (k == K_HOME) t->cur = e->mods & M_CTRL ? 0 : t->ln[l]; else if (k == K_END) t->cur = e->mods & M_CTRL ? t->len : at_col(t, l, 1 << 20); else if (k == K_UP) { if (l) t->cur = at_col(t, l - 1, col); } else if (k == K_DOWN) { if (l + 1 < t->nl) t->cur = at_col(t, l + 1, col); } else if (k == K_PGUP) t->cur = at_col(t, MAX(0, l - page), col); else if (k == K_PGDN) t->cur = at_col(t, MIN(t->nl - 1, l + page), col); else mv = 0; if (mv) { if (sh) { if (t->sel < 0) t->sel = c0; } else t->sel = -1; return 1; } long a = MIN(t->sel, t->cur), b = MAX(t->sel, t->cur); int has = t->sel >= 0 && a != b; if (e->ch == 1) { t->sel = 0; t->cur = t->len; return 1; } if (e->ch == 3 || e->ch == 24) { if (has) { z_clip_set(t->t + a, MIN(b - a, 65536L)); if (e->ch == 24) { del_sel(t); return 2; } } return 1; } if (e->ch == 22) { char *c = malloc(65536); int n = z_clip_get(c, 65536); del_sel(t); ins_(t, c, n); free(c); return 2; } if (e->ch == 8) { if (has) del_sel(t); else if (t->cur) { long s = t->cur - 1; while (s && (t->t[s] & 0xC0) == 0x80) s--; del_(t, s, t->cur); } return 2; } if (e->ch == 127) { if (has) del_sel(t); else if (t->cur < t->len) { long q = t->cur + 1; while (q < t->len && (t->t[q] & 0xC0) == 0x80) q++; del_(t, t->cur, q); } return 2; } if (e->ch == '\n' || e->ch == '\t' || e->ch >= 32) { del_sel(t); char u[4]; int n = utf8_put(e->ch, u); ins_(t, u, n); return 2; } return 0; }
void te_draw(zwin *w, te_t *t, int x, int y, int h, int sc, u32 fg, u32 selc, u32 curc, int center) { te_layout(t, t->cols); int ch = 18 * sc, cw = 8 * sc, vis = MAX(1, h / ch), cl = te_line_of(t, t->cur); if (center) t->top = MAX(0, cl - vis / 2); else { if (cl < t->top) t->top = cl; if (cl >= t->top + vis) t->top = cl - vis + 1; } long a = t->sel < 0 ? -1 : MIN(t->sel, t->cur), b = t->sel < 0 ? -1 : MAX(t->sel, t->cur); char u[5]; for (int r = 0; r < vis && t->top + r < t->nl; r++) { int l = t->top + r, c = 0; long p = t->ln[l], e = l + 1 < t->nl ? t->ln[l + 1] : t->len + 1; int Y = y + r * ch; while (p < e && p <= t->len) { if (p >= a && p < b && a >= 0) g_rect(w, x + c * cw, Y, cw, ch, selc); if (p == t->cur) g_rect(w, x + c * cw, Y, 2 * sc, 16 * sc, curc); if (p >= t->len || t->t[p] == '\n') break; const char *q = t->t + p; int cp = utf8_next(&q); int n = utf8_put(cp == '\t' ? ' ' : cp, u); u[n] = 0; if (sc > 1) g_text2(w, x + c * cw, Y, u, fg, sc); else g_text(w, x + c * cw, Y, u, fg); p = q - t->t; c++; } } }
/* clic en el texto: 1 clic pone el cursor, 2 eligen la palabra, 3 todo el texto; con ext (Mayus o arrastrar) amplia */
extern zevent z_last_down; static u64 te_multi;
static int te_wc(te_t *t, long i) { u8 c = t->t[i]; return c >= 0x80 || (c >= '0' && c <= '9') || ((c | 32) >= 'a' && (c | 32) <= 'z') || c == '_'; }
void te_click(te_t *t, int rx, int ry, int sc, int ext) { te_layout(t, t->cols); int l = MIN(t->top + MAX(ry, 0) / (18 * sc), t->nl - 1); long p = at_col(t, l, MAX(0, rx + 4 * sc) / (8 * sc));
    if (ext) { if (te_multi && z_ms() - te_multi < 600) return; if (t->sel < 0) t->sel = t->cur; t->cur = p; return; }
    int n = ui_clicks(&z_last_down); te_multi = 0;
    if (n >= 3) { t->sel = 0; t->cur = t->len; te_multi = z_ms(); return; }
    if (n == 2 && t->len) { long s = MIN(p, t->len), q; if (s == t->len || !te_wc(t, s)) { if (s > 0) s--; }
        if (te_wc(t, s)) { while (s > 0 && te_wc(t, s - 1)) s--; q = s; while (q < t->len && te_wc(t, q)) q++; } else q = s + 1;
        t->sel = s; t->cur = q; te_multi = z_ms(); return; }
    t->sel = -1; t->cur = p; }
int z_theme_save(const ztheme *t) { sb_t b = {0}; sb_s(&b, "ZTEMA1\n"); const u32 *p = (const u32 *)t; for (unsigned i = 0; i + 1 < sizeof *t / 4; i++) sb_f(&b, "%x\n", p[i]); int e = z_writefile("/sys/ZUNZUN/TEMA.TXT", b.p, b.n); free(b.p); return e; }
int z_theme_load(ztheme *t) { char *d = z_readfile("/sys/ZUNZUN/TEMA.TXT", 0); if (!d) return -2; if (strncmp(d, "ZTEMA1\n", 7)) { free(d); return -22; } u32 *p = (u32 *)t; char *q = d + 7; for (unsigned i = 0; i + 1 < sizeof *t / 4 && *q; i++) { u32 v = 0; while (*q && *q != '\n') { int c = tolower(*q++); v = v * 16 + (isdigit(c) ? c - '0' : c - 'a' + 10); } if (*q) q++; p[i] = v; } free(d); return 0; }
/* menu del boton derecho para cualquier cuadro de texto te_t: cortar, copiar, pegar y seleccionar todo */
int te_menu(zwin *w, te_t *t, zevent *e) { static const char *it[] = {"Cortar", "Copiar", "Pegar", "Seleccionar todo"}; int sx, sy; zw_screen(w, e->x, e->y, &sx, &sy);
    int r = ui_menu(sx, sy, it, 4); if (r < 0) return 0; static const int ch[] = {24, 3, 22, 1}; zevent k = {0}; k.type = EV_KEY; k.ch = ch[r]; k.mods = M_CTRL; return te_key(t, &k, 1); }
/* deshacer y rehacer (Ctrl+Z, Ctrl+Y o Ctrl+Mayus+Z) para todos los cuadros de texto te_t. Se guarda una copia
   del texto antes de cada grupo de cambios: escribir seguido cuenta como un solo cambio hasta una pausa de
   un segundo, un salto de linea o cambiar de escribir a borrar; pegar y cortar son siempre un cambio aparte. */
#define UMAX 40
typedef struct { char *t; long len, cur; } ust_t;
typedef struct { ust_t u[UMAX], r[UMAX]; int nu, nr, kind; u64 last; } undo_t;
static void ust_free(ust_t *s) { free(s->t); s->t = 0; }
static void undo_clear(te_t *t) { undo_t *u = t->undo; if (!u) return; for (int i = 0; i < u->nu; i++) ust_free(&u->u[i]); for (int i = 0; i < u->nr; i++) ust_free(&u->r[i]); u->nu = u->nr = 0; u->kind = 0; }
static ust_t snap(te_t *t) { ust_t s; s.t = malloc(t->len + 1); memcpy(s.t, t->t, t->len + 1); s.len = t->len; s.cur = t->cur; return s; }
static void apply(te_t *t, ust_t *s) { need(t, s->len); memcpy(t->t, s->t, s->len + 1); t->len = s->len; t->cur = MIN(s->cur, s->len); t->sel = -1; t->changed = 1; ust_free(s); }
static void push(ust_t *st, int *n, ust_t s) { if (*n == UMAX) { ust_free(&st[0]); memmove(st, st + 1, (UMAX - 1) * sizeof *st); (*n)--; } st[(*n)++] = s; }
int te_key(te_t *t, zevent *e, int page) {
    if (!t->undo) t->undo = calloc(1, sizeof(undo_t)); undo_t *u = t->undo; int ch = e->ch;
    if (ch == 26 || ch == 25) { int redo = ch == 25 || (e->mods & M_SHIFT); if (redo ? !u->nr : !u->nu) return 1;
        if (redo) { push(u->u, &u->nu, snap(t)); apply(t, &u->r[--u->nr]); } else { push(u->r, &u->nr, snap(t)); apply(t, &u->u[--u->nu]); } u->kind = 0;
        char lg[64]; snprintf(lg, 64, "[prueba] %s: %ld letras", redo ? "rehacer" : "deshacer", t->len); z_log(lg); return 2; }
    int has = t->sel >= 0 && t->sel != t->cur, kind = 0;
    if (ch == 22) kind = 3; else if (ch == 24) kind = has ? 3 : 0; else if (ch == 8 || ch == 127) kind = (ch == 8 ? t->cur > 0 : t->cur < t->len) || has ? 2 : 0; else if (ch == '\n' || ch == '\t' || ch >= 32) kind = 1;
    if (kind) { u64 now = z_ms(); if (kind == 3 || kind != u->kind || now - u->last > 1000 || ch == '\n' || has) { push(u->u, &u->nu, snap(t)); for (int i = 0; i < u->nr; i++) ust_free(&u->r[i]); u->nr = 0; }
        u->kind = kind == 3 ? 0 : kind; u->last = now; }
    else if (e->key == K_LEFT || e->key == K_RIGHT || e->key == K_UP || e->key == K_DOWN || e->key == K_HOME || e->key == K_END) u->kind = 0;
    return te_key0(t, e, page); }
